#include <stdint.h>
#include <stdbool.h>

typedef enum {
  STATUS_IDLE,
  STATUS_ACTIVE,
  STATUS_TIMEOUT
} StatusMode;

typedef struct {
  StatusMode mode;
  uint32_t active_ms;
} StatusController;

static volatile bool button_event = false;
static volatile uint32_t timer_ticks = 0;

void button_interrupt_handler(void) {
  // Kurz halten: Quelle quittieren und Ereignis übergeben.
  button_event = true;
}

void timer_interrupt_handler(void) {
  timer_ticks++;
}

static void set_led_bit(volatile uint32_t *output_register, uint32_t mask) {
  *output_register |= mask;
}

int main(void) {
  StatusController controller = { .mode = STATUS_IDLE, .active_ms = 0U };
  initialise_hardware();

  for (;;) {
    if (button_event) {
      button_event = false;
      controller.mode = STATUS_ACTIVE;
      controller.active_ms = 0U;
    }

    if (timer_ticks > 0U) {
      timer_ticks--;
      controller.active_ms += 1U;
    }

    update_status_output(&controller);
  }
}
